"""Media-generation providers (Part 2 — media GENERATED BY the model).

Anthropic/most chat LLMs cannot generate images/audio/video, so generation is an
external-provider TOOL. This is the one seam behind which every provider lives:
add a driver, register it in `get_image_provider`, and the `generate_image` tool
(tools/media_tools.py) works unchanged.

Config (dedicated `media.*`, not per-tenant Connections — first-class feature):
    media.image.provider  = openrouter | replicate | fal | openai
    media.image.model     = e.g. black-forest-labs/flux-schnell (replicate)
    media.gen.api_key     = provider token
    media.image.base_url  = override for the openrouter driver (optional)
    media.image.size      = e.g. 1024x1024
    media.gen.timeout_s   = sync-wait budget

Each driver returns (bytes, mime_type). Blocking HTTP — the tool calls it via
asyncio.to_thread so the event loop is never blocked.
"""

from __future__ import annotations

import logging
import re
from typing import Optional, Tuple

import requests

from core.config import app_config

logger = logging.getLogger("agent.media.gen")


class MediaGenProvider:
    def generate_image(self, prompt: str, size: str = None) -> Tuple[bytes, str]:
        raise NotImplementedError


def _download(url: str, timeout: int) -> Tuple[bytes, str]:
    r = requests.get(url, timeout=timeout)
    r.raise_for_status()
    mime = r.headers.get("content-type", "image/png").split(";")[0].strip()
    return r.content, (mime or "image/png")


class ReplicateImageProvider(MediaGenProvider):
    """Replicate. Uses the model-scoped predictions endpoint with `Prefer: wait`
    to get a synchronous result (falls back to polling if the model is slow).

    Polling is bounded to `_timeout` seconds total: the sync wait + subsequent
    polls must converge within budget. Each poll sleeps 1.5 s with a gentle
    backoff (×1.1, cap 5 s) so we don't hammer the API on slow models.
    """

    _TERMINAL = frozenset(("succeeded", "failed", "canceled"))

    def __init__(self, api_key: str, model: str, timeout_s: int = 90):
        self._key = api_key
        self._model = model
        self._timeout = timeout_s

    def _headers(self):
        return {"Authorization": f"Token {self._key}",
                "Content-Type": "application/json"}

    def generate_image(self, prompt: str, size: str = None) -> Tuple[bytes, str]:
        import time
        url = f"https://api.replicate.com/v1/models/{self._model}/predictions"
        body = {"input": {"prompt": prompt}}
        headers = {**self._headers(), "Prefer": "wait"}
        resp = requests.post(url, json=body, headers=headers, timeout=self._timeout)
        resp.raise_for_status()
        pred = resp.json()
        # Poll if not resolved by the sync wait — bounded by total timeout.
        get_url = (pred.get("urls") or {}).get("get")
        deadline = time.monotonic() + self._timeout
        delay = 1.5
        while (pred.get("status") not in self._TERMINAL
               and get_url
               and time.monotonic() < deadline):
            time.sleep(min(delay, max(deadline - time.monotonic(), 0.1)))
            pred = requests.get(
                get_url, headers=self._headers(), timeout=self._timeout
            ).json()
            delay = min(delay * 1.1, 5.0)
        if pred.get("status") != "succeeded":
            raise RuntimeError(f"image generation {pred.get('status')}: "
                               f"{pred.get('error') or 'no output'}")
        out = pred.get("output")
        out_url = out[0] if isinstance(out, list) and out else out
        if not isinstance(out_url, str):
            raise RuntimeError("image generation returned no URL")
        return _download(out_url, self._timeout)


class FalImageProvider(MediaGenProvider):
    """fal.ai — synchronous run endpoint returns image URLs."""

    def __init__(self, api_key: str, model: str, timeout_s: int = 90):
        self._key = api_key
        self._model = model
        self._timeout = timeout_s

    def generate_image(self, prompt: str, size: str = None) -> Tuple[bytes, str]:
        url = f"https://fal.run/{self._model}"
        headers = {"Authorization": f"Key {self._key}", "Content-Type": "application/json"}
        resp = requests.post(url, json={"prompt": prompt}, headers=headers,
                             timeout=self._timeout)
        resp.raise_for_status()
        data = resp.json()
        imgs = data.get("images") or []
        out_url = imgs[0].get("url") if imgs and isinstance(imgs[0], dict) else None
        if not out_url:
            raise RuntimeError("fal returned no image")
        return _download(out_url, self._timeout)


class OpenAIImageProvider(MediaGenProvider):
    """OpenAI Images — model-aware request builder.

    gpt-image-1 uses `output_format` ("png"|"jpeg"|"webp") and always returns
    `b64_json` in each data item. dall-e-3 uses `response_format` ("b64_json"|
    "url"). We detect the variant and send the correct parameter so every model
    returns base64 without relying on a fragile URL download.
    """

    def __init__(self, api_key: str, model: str, timeout_s: int = 90):
        self._key = api_key
        self._model = model or "gpt-image-1"
        self._timeout = timeout_s

    def _is_gpt_image(self) -> bool:
        return "gpt-image" in self._model.lower()

    def generate_image(self, prompt: str, size: str = None) -> Tuple[bytes, str]:
        import base64 as b64mod
        body: dict = {"model": self._model, "prompt": prompt,
                      "size": size or "1024x1024"}
        # gpt-image-1: `output_format` controls encoding (always returns b64).
        # dall-e-3: `response_format` controls b64 vs URL.
        if self._is_gpt_image():
            body["output_format"] = "png"
        else:
            body["response_format"] = "b64_json"

        resp = requests.post(
            "https://api.openai.com/v1/images/generations",
            headers={"Authorization": f"Bearer {self._key}",
                     "Content-Type": "application/json"},
            json=body, timeout=self._timeout)
        resp.raise_for_status()
        d = resp.json()["data"][0]
        if d.get("b64_json"):
            return b64mod.b64decode(d["b64_json"]), "image/png"
        # Fallback (should not be reached with correct params above).
        if d.get("url"):
            return _download(d["url"], self._timeout)
        raise RuntimeError("OpenAI returned neither b64_json nor url")


class OpenRouterImageProvider(MediaGenProvider):
    """OpenRouter — image generation over the CHAT-COMPLETIONS endpoint.

    <b>Why this driver exists at all.</b> The tenant already authenticates to
    OpenRouter for every text turn (`llm.api_key`, `llm.base_url`), and that one
    credential reaches eleven image-output models. The alternative — a second
    provider with a second key — is a second bill, a second rate limit and a
    second thing to rotate, for a capability the existing account already has.

    <b>Not the /images endpoint.</b> OpenRouter has no OpenAI-style
    `/images/generations`. Image models are driven through `/chat/completions`
    with `modalities: ["image", "text"]`, and the picture comes back on the
    MESSAGE rather than in `content`:

        choices[0].message.images[0] = {
            "type": "image_url",
            "image_url": {"url": "data:image/png;base64,..."}
        }

    Verified against `google/gemini-2.5-flash-image` and
    `openai/gpt-5-image-mini` on 2026-08-26. Both return a data URI, so there is
    no second round trip to download — unlike Replicate and fal, which hand back
    a URL.

    <b>`size` is not a parameter here.</b> The chat-completions image path has no
    size field; a model decides its own dimensions. It is accepted for interface
    compatibility and folded into the prompt as a hint, which is the only lever
    that exists. Silently ignoring it would leave a caller believing it worked.
    """

    _DATA_URI = re.compile(r"^data:(?P<mime>[^;,]+);base64,(?P<b64>.+)$", re.S)

    def __init__(self, api_key: str, model: str, timeout_s: int = 90,
                 base_url: str = None):
        self._key = api_key
        self._model = model or "google/gemini-2.5-flash-image"
        self._timeout = timeout_s
        # Default to the completions URL, but accept a configured base so a
        # deployment behind a proxy does not need a code change.
        self._url = (base_url or "https://openrouter.ai/api/v1/chat/completions")

    def generate_image(self, prompt: str, size: str = None) -> Tuple[bytes, str]:
        import base64 as b64mod

        text = prompt if not size else f"{prompt}\n\nAspect/size hint: {size}."
        body = {
            "model": self._model,
            "messages": [{"role": "user", "content": text}],
            "modalities": ["image", "text"],
        }
        resp = requests.post(
            self._url,
            headers={"Authorization": f"Bearer {self._key}",
                     "Content-Type": "application/json"},
            json=body, timeout=self._timeout)
        resp.raise_for_status()
        payload = resp.json()

        choices = payload.get("choices") or []
        message = (choices[0].get("message") or {}) if choices else {}
        images = message.get("images") or []
        if not images:
            # A refusal arrives as a normal 200 with no image and a reason. Say
            # which, because "no image" and "the model declined" are different
            # problems and only one of them is worth retrying.
            refusal = message.get("refusal") or (message.get("content") or "")
            raise RuntimeError(
                f"OpenRouter returned no image"
                + (f": {str(refusal)[:200]}" if refusal else ""))

        first = images[0]
        url = first.get("image_url") if isinstance(first, dict) else None
        url = url.get("url") if isinstance(url, dict) else url
        if not isinstance(url, str) or not url:
            raise RuntimeError("OpenRouter image entry carried no url")

        m = self._DATA_URI.match(url)
        if m:
            return b64mod.b64decode(m.group("b64")), (m.group("mime") or "image/png")
        # Some models may hand back a hosted URL instead of a data URI.
        return _download(url, self._timeout)


def get_image_provider() -> Optional[MediaGenProvider]:
    """The configured image provider, or None (no provider / no key) — in which
    case the generate_image tool is not exposed and output.image is reported
    unsupported."""
    provider = (app_config.get("media.image.provider") or "").strip().lower()
    key = app_config.get("media.gen.api_key")
    model = app_config.get("media.image.model")
    timeout = int(app_config.get("media.gen.timeout_s", "90") or 90)
    if not provider or not key:
        return None
    try:
        if provider == "replicate":
            return ReplicateImageProvider(key, model, timeout)
        if provider == "fal":
            return FalImageProvider(key, model, timeout)
        if provider == "openai":
            return OpenAIImageProvider(key, model, timeout)
        if provider == "openrouter":
            return OpenRouterImageProvider(
                key, model, timeout, app_config.get("media.image.base_url"))
    except Exception as e:
        logger.warning("image provider init failed (%s)", e)
    return None


def image_generation_available() -> bool:
    return get_image_provider() is not None
